    wchar_t name[128];if(!sg_named(name,L"Stop",s->owner.pid,s->nonce)){failure("invalid_session_nonce",0);goto done;}HANDLE event=OpenEventW(EVENT_MODIFY_STATE,FALSE,name);if(!event){failure("private_stop_channel_unavailable",GetLastError());goto done;}bool ok=SetEvent(event)!=FALSE;DWORD code=ok?0:GetLastError();CloseHandle(event);if(!ok){failure("private_stop_signal_failed",code);goto done;}puts("{\"ok\":true,\"status\":\"stop_requested\",\"scope\":\"owned launcher Job only; no PID-based termination\"}");result=0;
