    if(!wcscmp(argv[1],L"run"))return run(argc,argv);if(!wcscmp(argv[1],L"capture"))return capture(argc,argv);if(!wcscmp(argv[1],L"stop"))return stop_session(argc,argv);return failure("unknown_command",0);
